def safe_divide(a: float, b: float) -> float:
    if b == 0:
        raise ZeroDivisionError('division by zero')
    return a / b

c_test:
#include <stdio.h>
#include <math.h>
int main(void){int p=0,t=0; double r;
 t++; p+= (safe_divide(6,3,&r)==0 && fabs(r-2.0)<1e-9);
 t++; p+= (safe_divide(1,0,&r)==-1);
 t++; p+= (safe_divide(-9,3,&r)==0 && fabs(r+3.0)<1e-9);
 printf("%d/%d\n",p,t); return p!=t;}

