def parse_int_or(s: str, fallback: int) -> int:
    try:
        return int(s)
    except ValueError:
        return fallback

c_test:
#include <stdio.h>
int main(void){int p=0,t=0;
 t++; p+= parse_int_or("42",-1)==42;
 t++; p+= parse_int_or("abc",-1)==-1;
 t++; p+= parse_int_or("",7)==7;
 t++; p+= parse_int_or("-13",0)==-13;
 t++; p+= parse_int_or("12x",99)==99;
 printf("%d/%d\n",p,t); return p!=t;}

