class Counter:
    def __init__(self):
        self.value = 0

    def add(self, n: int):
        self.value += n

    def reset(self):
        self.value = 0

    def get(self) -> int:
        return self.value

c_signature:
typedef struct { int value; } Counter;
void counter_init(Counter *c);
void counter_add(Counter *c, int n);
void counter_reset(Counter *c);
int counter_get(const Counter *c);

c_test:
#include <stdio.h>
int main(void){int p=0,t=0; Counter c;
 counter_init(&c); t++; p+= counter_get(&c)==0;
 counter_add(&c,5); counter_add(&c,3); t++; p+= counter_get(&c)==8;
 counter_add(&c,-10); t++; p+= counter_get(&c)==-2;
 counter_reset(&c); t++; p+= counter_get(&c)==0;
 printf("%d/%d\n",p,t); return p!=t;}

python:
def squares(n: int):
    for i in range(n):
        yield i * i

c_signature:
typedef struct { int i; int n; } SquareGen;
void squares_init(SquareGen *g, int n);
bool squares_next(SquareGen *g, int *out);   /* false when exhausted */

c_test:
#include <stdio.h>
int main(void){int p=0,t=0; SquareGen g; int v, k=0, got[8];
 squares_init(&g,4);
 while(squares_next(&g,&v) && k<8) got[k++]=v;
 t++; p+= (k==4 && got[0]==0 && got[1]==1 && got[2]==4 && got[3]==9);
 squares_init(&g,0); t++; p+= (squares_next(&g,&v)==false);
 squares_init(&g,1); t++; p+= (squares_next(&g,&v)==true && v==0 && squares_next(&g,&v)==false);
 printf("%d/%d\n",p,t); return p!=t;}

