from typing import List, Optional

def find_index(l: List[int], target: int) -> Optional[int]:
    for i, x in enumerate(l):
        if x == target:
            return i
    return None

c_test:
#include <stdio.h>
int main(void){int p=0,t=0; size_t idx;
 int a[]={4,7,9};
 t++; p+= (find_index(a,3,7,&idx)==true && idx==1);
 t++; p+= (find_index(a,3,4,&idx)==true && idx==0);
 t++; p+= (find_index(a,3,5,&idx)==false);
 t++; p+= (find_index(NULL,0,1,&idx)==false);
 printf("%d/%d\n",p,t); return p!=t;}

