from typing import List

def flatten_evens(grid: List[List[int]]) -> List[int]:
    return [x for row in grid for x in row if x % 2 == 0]

c_test:
#include <stdio.h>
#include <stdlib.h>
int main(void){int p=0,t=0; size_t k; int *r;
 int g[]={1,2,3, 4,5,6};
 r=flatten_evens(g,2,3,&k); t++; p+=(k==3 && r[0]==2 && r[1]==4 && r[2]==6); free(r);
 int h[]={1,3,5}; r=flatten_evens(h,1,3,&k); t++; p+=(k==0); free(r);
 r=flatten_evens(NULL,0,0,&k); t++; p+=(k==0); free(r);
 printf("%d/%d\n",p,t); return p!=t;}
